namespace StokTakipUygulamasi;
internal sealed class frmGiris:Form
{
    public Session? User {get;private set;}
    public frmGiris(){Ui.Setup(this,"Stok Takip • Giriş",500,540);FormBorderStyle=FormBorderStyle.FixedDialog;MaximizeBox=false;MinimumSize=Size.Empty;var first=Db.Query("SELECT id FROM personeller LIMIT 1").Rows.Count==0;
        var root=UiLayout.Root(this,1);root.Padding=new Padding(36);var card=UiLayout.Card(1,8);card.Padding=new Padding(28);UiLayout.Add(root,card,0,0);UiLayout.Row(card,0,64);UiLayout.Row(card,1,36);UiLayout.Row(card,2,30);UiLayout.Row(card,3,68);UiLayout.Row(card,4,68);UiLayout.Row(card,5,54);UiLayout.Row(card,6,46);UiLayout.Row(card,7,100,false);
        var title=UiLayout.Heading("STOK TAKİP",25);title.TextAlign=ContentAlignment.MiddleCenter;UiLayout.Add(card,title,0,0);var subtitle=UiLayout.Heading(first?"İlk kurulum":"Tekrar hoş geldiniz",12);subtitle.TextAlign=ContentAlignment.MiddleCenter;subtitle.ForeColor=Theme.Accent;UiLayout.Add(card,subtitle,0,1);var desc=UiLayout.Caption(first?"Yönetici hesabınızı oluşturun.":"Devam etmek için hesabınıza giriş yapın.");desc.TextAlign=ContentAlignment.MiddleCenter;UiLayout.Add(card,desc,0,2);
        var name=UiLayout.Text();var pass=UiLayout.Text();pass.UseSystemPasswordChar=true;UiLayout.Add(card,UiLayout.Field("Kullanıcı adı",name),0,3,margin:new Padding(0,10,0,4));UiLayout.Add(card,UiLayout.Field("Şifre",pass),0,4,margin:new Padding(0,10,0,4));if(first)name.Text="admin";
        var options=UiLayout.Table(1,2,Theme.Surface);UiLayout.Row(options,0,25);UiLayout.Row(options,1,100,false);var show=new CheckBox{Text="Şifreyi göster",AutoSize=true,ForeColor=Theme.Muted};show.CheckedChanged+=(_,_)=>pass.UseSystemPasswordChar=!show.Checked;UiLayout.Add(options,show,0,0);UiLayout.Add(options,UiLayout.Caption(first?"En az 8 karakterli bir şifre belirleyin.":""),0,1);UiLayout.Add(card,options,0,5);var submit=UiLayout.Button(first?"Hesap oluştur":"Giriş yap",()=>{var n=name.Text.Trim();if(n.Length==0||pass.Text.Length==0)throw new InvalidOperationException("Kullanıcı adı ve şifre giriniz.");if(first){if(pass.Text.Length<8)throw new InvalidOperationException("Şifre en az 8 karakter olmalı.");Db.Exec("INSERT INTO personeller(ad,soyad,telefon,kullanici_adi,sifre,yetki_id) VALUES('Sistem','Yöneticisi','0000000000',@p0,@p1,1)",n,Db.Password(pass.Text));}var d=Db.Query("SELECT id,ad,soyad,sifre,yetki_id FROM personeller WHERE kullanici_adi=@p0",n);if(d.Rows.Count!=1||!Db.Verify(pass.Text,Db.Str(d.Rows[0][3]))){Ui.Info("Kullanıcı adı veya şifre hatalı.");return;}var r=d.Rows[0];User=new Session(Db.Number(r[0]),Db.Str(r[1])+" "+Db.Str(r[2]),Db.Number(r[4]));DialogResult=DialogResult.OK;},true);UiLayout.Add(card,submit,0,6);AcceptButton=submit;var version=UiLayout.Caption("© 2026 heavenylz");version.TextAlign=ContentAlignment.MiddleCenter;UiLayout.Add(card,version,0,7);
        if(Theme.Motion){root.Visible=false;AcceptButton=null;var splash=new SplashSurface{Dock=DockStyle.Fill};Controls.Add(splash);splash.BringToFront();Opacity=.05;Shown+=(_,_)=>{Theme.Fade(this,300);Theme.Animate(splash,1450,t=>{splash.Progress=t;splash.Invalidate();},()=>{if(IsDisposed)return;Theme.Animate(splash,220,t=>{splash.Reveal=1-t;splash.Invalidate();},()=>{if(IsDisposed)return;Opacity=.05;splash.Dispose();root.Visible=true;title.Reveal=0;subtitle.Reveal=0;Theme.Fade(this,450);Theme.Animate(title,850,t=>{title.Reveal=t;title.Invalidate();subtitle.Reveal=Math.Clamp((t-.30)/.70,0,1);subtitle.Invalidate();},()=>{AcceptButton=submit;name.Focus();});});});};}else Shown+=(_,_)=>name.Focus();
    }
}
internal sealed class SplashSurface:Panel
{
    internal double Progress{get;set;} internal double Reveal{get;set;}=1;
    internal SplashSurface(){BackColor=Theme.Background;DoubleBuffered=true;}
    protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);var g=e.Graphics;g.SmoothingMode=System.Drawing.Drawing2D.SmoothingMode.AntiAlias;float x=Width/2f,y=Height/2f-32;double alpha=Reveal*Math.Min(1,Progress*4);using var ring=new Pen(Theme.Mix(Theme.Background,Theme.Accent,alpha),2.5f);using var dim=new Pen(Theme.Mix(Theme.Background,Theme.Border,Reveal),2);g.DrawEllipse(dim,x-32,y-76,64,64);g.DrawArc(ring,x-32,y-76,64,64,-90+(float)(Progress*300),85+(float)(Progress*180));using var font=new Font("Segoe UI",23,FontStyle.Bold);using var small=new Font("Segoe UI",10);using var fmt=new StringFormat{Alignment=StringAlignment.Center,LineAlignment=StringAlignment.Center};var r=new RectangleF(0,y+5,Width,52);for(int i=1;i<=4;i++){using var glow=new SolidBrush(Color.FromArgb((int)(20*alpha),Theme.Accent));g.DrawString("STOK TAKİP",font,glow,new RectangleF(r.X-i,r.Y,r.Width+2*i,r.Height),fmt);}using var text=new SolidBrush(Theme.Mix(Theme.Background,Theme.Text,alpha));g.DrawString("STOK TAKİP",font,text,r,fmt);using var muted=new SolidBrush(Theme.Mix(Theme.Background,Theme.Muted,Reveal*Math.Clamp((Progress-.15)*3,0,1)));g.DrawString("Çalışma alanı hazırlanıyor",small,muted,new RectangleF(0,y+65,Width,25),fmt);float w=Width*.48f;using var track=new SolidBrush(Theme.Mix(Theme.Background,Theme.Border,Reveal));using var bar=new SolidBrush(Theme.Mix(Theme.Background,Theme.Accent,Reveal));g.FillRectangle(track,x-w/2,y+108,w,3);g.FillRectangle(bar,x-w/2,y+108,(float)(w*Progress),3);}
}
